package br.com.stockmanager.service;
import br.com.stockmanager.dto.*; import br.com.stockmanager.entity.*; import br.com.stockmanager.enums.*; import br.com.stockmanager.exception.*; import br.com.stockmanager.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class StockMovementService{
 private final StockMovementRepository movements; private final ProductService products; private final SupplierService suppliers; private final UserRepository users;
 public StockMovementService(StockMovementRepository movements,ProductService products,SupplierService suppliers,UserRepository users){this.movements=movements;this.products=products;this.suppliers=suppliers;this.users=users;}
 @Transactional public MovementResponse create(MovementType type,MovementRequest r,String email){User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResourceNotFoundException("Usuário não encontrado."));Supplier s=r.supplierId()==null?null:suppliers.get(r.supplierId());if(s!=null&&!s.isActive())throw new BusinessException("Fornecedor inativo.");if(type==MovementType.ENTRY&&r.items().stream().anyMatch(i->i.unitCost()==null||i.unitCost().signum()<0))throw new BusinessException("Custo unitário é obrigatório nas entradas.");if(type==MovementType.EXIT&&(r.reason()==null||(r.reason()==ExitReason.OTHER&&(r.description()==null||r.description().isBlank()))))throw new BusinessException("Motivo e descrição da saída são obrigatórios.");if(type==MovementType.ADJUSTMENT&&(r.description()==null||r.description().isBlank()))throw new BusinessException("Justificativa do ajuste é obrigatória.");StockMovement m=new StockMovement(type,r.description(),r.reason()==null?null:r.reason().name(),s,u);
  for(MovementItemRequest ir:r.items()){Product p=products.get(ir.productId());if(!p.isActive())throw new BusinessException("Produto inativo: "+p.getSku());BigDecimal old=p.getCurrentStock();BigDecimal result=type==MovementType.ENTRY?old.add(ir.quantity()):type==MovementType.EXIT?old.subtract(ir.quantity()):adjust(old,ir);if(result.signum()<0)throw new BusinessException("Estoque insuficiente para o produto "+p.getSku()+".");if(type==MovementType.ENTRY){BigDecimal cost=ir.unitCost();BigDecimal total=old.multiply(p.getCostPrice()).add(ir.quantity().multiply(cost));p.setCostPrice(total.divide(result,4,RoundingMode.HALF_UP));}p.setCurrentStock(result);m.addItem(new StockMovementItem(p,ir.quantity(),type==MovementType.ADJUSTMENT?ir.adjustmentDirection():null,old,result,ir.unitCost()));}
  return toResponse(movements.save(m));
 }
 private BigDecimal adjust(BigDecimal old,MovementItemRequest r){if(r.adjustmentDirection()==null)throw new BusinessException("Direção do ajuste é obrigatória.");return r.adjustmentDirection()==AdjustmentDirection.INCREASE?old.add(r.quantity()):old.subtract(r.quantity());}
 @Transactional(readOnly=true) public List<MovementResponse> findAll(){return movements.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt")).stream().map(this::toResponse).toList();}
 @Transactional(readOnly=true) public MovementResponse get(Long id){return toResponse(movements.findById(id).orElseThrow(()->new ResourceNotFoundException("Movimentação não encontrada.")));}
 private MovementResponse toResponse(StockMovement m){return new MovementResponse(m.getId(),m.getType(),m.getDescription(),m.getReason(),m.getCreatedAt(),m.getItems().stream().map(i->new MovementResponse.Item(i.getProduct().getId(),i.getProduct().getSku(),i.getProduct().getName(),i.getQuantity(),i.getPreviousStock(),i.getResultingStock(),i.getUnitCost())).toList());}
}
